    // -------------------------------------------------------------------------
    // Failure classification tests
    // -------------------------------------------------------------------------

    @Test
    void upload_setsRetryableTrueOnGeminiTimeout() throws IOException {
        byte[] pdfBytes = createMinimalPdf("Purchase order text content");
        MockMultipartFile file = new MockMultipartFile(
                "file", "po.pdf", "application/pdf", pdfBytes);

        when(documentRepository.findByUserIdAndFileHash(eq(1L), anyString()))
                .thenReturn(Optional.empty());
        when(userRepository.findById(1L)).thenReturn(Optional.of(testUser));

        Document savedDoc = new Document();
        savedDoc.setId(99L);
        savedDoc.setUser(testUser);
        savedDoc.setFileName("po.pdf");
        savedDoc.setFileType("application/pdf");
        savedDoc.setStatus(DocumentStatus.PROCESSING);
        savedDoc.setUploadedAt(LocalDateTime.now());
        when(documentRepository.save(any())).thenAnswer(inv -> {
            Document d = inv.getArgument(0);
            d.setId(99L);
            return d;
        });

        // Gemini throws timeout
        when(llmExtractionService.extract(anyString()))
                .thenThrow(new RuntimeException("connection timeout exceeded"));

        DocumentResponse response = documentService.upload(file, 1L);

        assertThat(response.status()).isEqualTo(DocumentStatus.FAILED);
        assertThat(response.retryable()).isTrue();
        assertThat(response.errorMessage()).contains("temporary service issue");
    }

    @Test
    void upload_setsRetryableFalseOnPermanentGeminiFailure() throws IOException {
        byte[] pdfBytes = createMinimalPdf("Purchase order text content");
        MockMultipartFile file = new MockMultipartFile(
                "file", "po.pdf", "application/pdf", pdfBytes);

        when(documentRepository.findByUserIdAndFileHash(eq(1L), anyString()))
                .thenReturn(Optional.empty());
        when(userRepository.findById(1L)).thenReturn(Optional.of(testUser));

        when(documentRepository.save(any())).thenAnswer(inv -> {
            Document d = inv.getArgument(0);
            d.setId(99L);
            return d;
        });

        // Gemini throws a permanent parse error (not timeout/connection)
        when(llmExtractionService.extract(anyString()))
                .thenThrow(new RuntimeException("Failed to parse Gemini response as JSON: unexpected token"));

        DocumentResponse response = documentService.upload(file, 1L);

        assertThat(response.status()).isEqualTo(DocumentStatus.FAILED);
        assertThat(response.retryable()).isFalse();
        assertThat(response.errorMessage()).contains("scanned image or an unsupported format");
    }

    @Test
    void getByUser_returnsListWithRetryableFields() {
        Document doc = new Document();
        doc.setId(1L);
        doc.setUser(testUser);
        doc.setFileName("po.pdf");
        doc.setFileType("application/pdf");
        doc.setStatus(DocumentStatus.FAILED);
        doc.setUploadedAt(LocalDateTime.now());
        doc.setRetryable(true);
        doc.setErrorMessage("Temporary failure");

        when(documentRepository.findByUserId(1L)).thenReturn(List.of(doc));

        List<DocumentResponse> responses = documentService.getByUser(1L);
        assertThat(responses).hasSize(1);
        assertThat(responses.get(0).retryable()).isTrue();
        assertThat(responses.get(0).errorMessage()).isEqualTo("Temporary failure");
    }

    // -------------------------------------------------------------------------
    // Duplicate handling based on status (5 required tests)
    // -------------------------------------------------------------------------

    /** 1. failed retryable → same file upload → reprocessing succeeds */
    @Test
    void upload_retryableFailedDocument_sameFile_reprocessesSuccessfully() throws Exception {
        byte[] pdfBytes = createMinimalPdf("Purchase order content for retry");
        MockMultipartFile file = new MockMultipartFile(
                "file", "po.pdf", "application/pdf", pdfBytes);

        Document existing = makeDoc(10L, testUser, DocumentStatus.FAILED);
        existing.setRetryable(true);
        existing.setFileHash("will-be-matched");

        when(documentRepository.findByUserIdAndFileHash(eq(1L), anyString()))
                .thenReturn(Optional.of(existing));
        when(documentRepository.save(any())).thenAnswer(inv -> inv.getArgument(0));
        when(userRepository.findById(1L)).thenReturn(Optional.of(testUser));

        ExtractedPurchaseOrder extractedPO = new ExtractedPurchaseOrder(
                "PO-001", "Supplier", "2025-01-01", "2025-02-01", "Net30", "USD",
                100.0, 10.0, 110.0, List.of());
        when(llmExtractionService.extract(anyString())).thenReturn(extractedPO);

        ValidationResult validationResult = new ValidationResult(
                DocumentStatus.COMPLETED, List.of(), List.of());
        when(poValidationService.validate(any())).thenReturn(validationResult);

        PurchaseOrder savedPo = new PurchaseOrder();
        savedPo.setId(55L);
        when(purchaseOrderRepository.save(any())).thenReturn(savedPo);

        DocumentResponse response = documentService.upload(file, 1L);

        // Same document record reused — not a new duplicate
        assertThat(response.duplicate()).isFalse();
        assertThat(response.retryProcessing()).isTrue();
        assertThat(response.id()).isEqualTo(10L);
        assertThat(response.status()).isEqualTo(DocumentStatus.COMPLETED);
        // Verify no second document was created (save only called for the existing one)
        verify(documentRepository, never()).save(argThat(d -> !d.getId().equals(10L)));
    }

    /** 2. failed non-retryable → same file → rejected as duplicate */
    @Test
    void upload_nonRetryableFailedDocument_sameFile_rejectedAsDuplicate() throws IOException {
        byte[] pdfBytes = createMinimalPdf("Purchase order content");
        MockMultipartFile file = new MockMultipartFile(
                "file", "po.pdf", "application/pdf", pdfBytes);

        Document existing = makeDoc(20L, testUser, DocumentStatus.FAILED);
        existing.setRetryable(false);

        when(documentRepository.findByUserIdAndFileHash(eq(1L), anyString()))
                .thenReturn(Optional.of(existing));

        DocumentResponse response = documentService.upload(file, 1L);

        assertThat(response.duplicate()).isTrue();
        assertThat(response.retryProcessing()).isFalse();
        assertThat(response.id()).isEqualTo(20L);
        verify(documentRepository, never()).save(any());
        verifyNoInteractions(llmExtractionService);
    }

    /** 3. completed document → same file → rejected as duplicate */
    @Test
    void upload_completedDocument_sameFile_rejectedAsDuplicate() throws IOException {
        byte[] pdfBytes = createMinimalPdf("Purchase order content");
        MockMultipartFile file = new MockMultipartFile(
                "file", "po.pdf", "application/pdf", pdfBytes);

        Document existing = makeDoc(30L, testUser, DocumentStatus.COMPLETED);

        when(documentRepository.findByUserIdAndFileHash(eq(1L), anyString()))
                .thenReturn(Optional.of(existing));

        DocumentResponse response = documentService.upload(file, 1L);

        assertThat(response.duplicate()).isTrue();
        assertThat(response.retryProcessing()).isFalse();
        verifyNoInteractions(llmExtractionService);
    }

    /** 4. processing document → same file → no second processing started */
    @Test
    void upload_processingDocument_sameFile_noSecondProcessing() throws IOException {
        byte[] pdfBytes = createMinimalPdf("Purchase order content");
        MockMultipartFile file = new MockMultipartFile(
                "file", "po.pdf", "application/pdf", pdfBytes);

        Document existing = makeDoc(40L, testUser, DocumentStatus.PROCESSING);

        when(documentRepository.findByUserIdAndFileHash(eq(1L), anyString()))
                .thenReturn(Optional.of(existing));

        DocumentResponse response = documentService.upload(file, 1L);

        assertThat(response.duplicate()).isTrue();
        assertThat(response.retryProcessing()).isFalse();
        assertThat(response.status()).isEqualTo(DocumentStatus.PROCESSING);
        verifyNoInteractions(llmExtractionService);
        verify(documentRepository, never()).save(any());
    }

    /** 5. retry succeeds → only one document/PO exists */
    @Test
    void upload_retryableFailure_retrySucceeds_onlyOneDocumentAndPoExist() throws Exception {
        byte[] pdfBytes = createMinimalPdf("Purchase order content unique retry test");
        MockMultipartFile file = new MockMultipartFile(
                "file", "po.pdf", "application/pdf", pdfBytes);

        Document existing = makeDoc(50L, testUser, DocumentStatus.FAILED);
        existing.setRetryable(true);
        existing.setFileHash("hash-match");

        when(documentRepository.findByUserIdAndFileHash(eq(1L), anyString()))
                .thenReturn(Optional.of(existing));
        when(documentRepository.save(any())).thenAnswer(inv -> inv.getArgument(0));
        when(userRepository.findById(1L)).thenReturn(Optional.of(testUser));

        ExtractedPurchaseOrder extractedPO = new ExtractedPurchaseOrder(
                "PO-999", "Vendor", "2025-03-01", "2025-04-01", "Net60", "EUR",
                200.0, 20.0, 220.0, List.of());
        when(llmExtractionService.extract(anyString())).thenReturn(extractedPO);

        ValidationResult validationResult = new ValidationResult(
                DocumentStatus.COMPLETED, List.of(), List.of());
        when(poValidationService.validate(any())).thenReturn(validationResult);

        PurchaseOrder savedPo = new PurchaseOrder();
        savedPo.setId(77L);
        when(purchaseOrderRepository.save(any())).thenReturn(savedPo);

        DocumentResponse response = documentService.upload(file, 1L);

        // Exactly one document record (id=50) and one PO (id=77)
        assertThat(response.id()).isEqualTo(50L);
        assertThat(response.purchaseOrderId()).isEqualTo(77L);
        assertThat(response.retryProcessing()).isTrue();
        // purchaseOrderRepository.save called exactly once
        verify(purchaseOrderRepository, times(1)).save(any());
        // No new document was inserted (save only called for existing doc)
        verify(documentRepository, never()).save(argThat(d -> d.getId() == null));
    }

    // -------------------------------------------------------------------------
    // Helper: create a minimal valid PDF with extractable text
    // -------------------------------------------------------------------------

    private byte[] createMinimalPdf(String text) throws IOException {
        try (PDDocument doc = new PDDocument();
             ByteArrayOutputStream baos = new ByteArrayOutputStream()) {
            org.apache.pdfbox.pdmodel.PDPage page = new org.apache.pdfbox.pdmodel.PDPage();
            doc.addPage(page);
            try (org.apache.pdfbox.pdmodel.PDPageContentStream cs =
                         new org.apache.pdfbox.pdmodel.PDPageContentStream(doc, page)) {
                cs.beginText();
                cs.setFont(
                        new org.apache.pdfbox.pdmodel.font.PDType1Font(
                                org.apache.pdfbox.pdmodel.font.Standard14Fonts.FontName.HELVETICA),
                        12
                );
                cs.newLineAtOffset(50, 700);
                cs.showText(text);
                cs.endText();
            }
            doc.save(baos);
            return baos.toByteArray();
        }
    }
}

package org.example.document;

import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.example.auth.UserRepository;
import org.example.entity.Document;
import org.example.entity.DocumentStatus;
import org.example.entity.PurchaseOrder;
import org.example.entity.User;
import org.example.purchaseorder.PurchaseOrderRepository;
import org.example.validation.PoValidationService;
import org.example.validation.ValidationResult;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.http.HttpStatus;
import org.springframework.mock.web.MockMultipartFile;
import org.springframework.web.server.ResponseStatusException;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

import static org.assertj.core.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for DocumentService — DOCX validation and text extraction.
 */
@ExtendWith(MockitoExtension.class)
class DocxDocumentServiceTest {

    @Mock DocumentRepository documentRepository;
    @Mock UserRepository userRepository;
    @Mock LlmExtractionService llmExtractionService;
    @Mock PurchaseOrderRepository purchaseOrderRepository;
    @Mock PoValidationService poValidationService;
    @Mock ObjectMapper objectMapper;

    @InjectMocks DocumentService documentService;

    private User testUser;

    @BeforeEach
    void setUp() {
        testUser = new User();
        testUser.setId(1L);
        testUser.setEmail("test@example.com");
    }

    // -----------------------------------------------------------------------
    // Helper: create a real DOCX byte array with given text content
    // -----------------------------------------------------------------------
    private byte[] buildDocxBytes(String paragraphText) throws IOException {
        try (XWPFDocument doc = new XWPFDocument()) {
            if (paragraphText != null && !paragraphText.isBlank()) {
                doc.createParagraph().createRun().setText(paragraphText);
            }
            ByteArrayOutputStream out = new ByteArrayOutputStream();
            doc.write(out);
            return out.toByteArray();
        }
    }

    private byte[] buildEmptyDocxBytes() throws IOException {
        return buildDocxBytes(null);
    }

    // -----------------------------------------------------------------------
    // DOCX validation — accepted content type
    // -----------------------------------------------------------------------

    @Test
    void upload_docxContentType_acceptedAndPersisted() throws Exception {
        byte[] docxBytes = buildDocxBytes("PO Number: 12345\nVendor: ACME Corp\nTotal: 500.00");

        MockMultipartFile file = new MockMultipartFile(
                "file", "order.docx",
                "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                docxBytes);

        when(documentRepository.findByUserIdAndFileHash(anyLong(), anyString()))
                .thenReturn(Optional.empty());
        when(userRepository.findById(1L)).thenReturn(Optional.of(testUser));

        Document savedDoc = new Document();
        savedDoc.setId(10L);
        savedDoc.setUser(testUser);
        savedDoc.setFileName("order.docx");
        savedDoc.setFileType("application/vnd.openxmlformats-officedocument.wordprocessingml.document");
        savedDoc.setStatus(DocumentStatus.PROCESSING);
        savedDoc.setUploadedAt(LocalDateTime.now());
        when(documentRepository.save(any(Document.class))).thenReturn(savedDoc);

        ExtractedPurchaseOrder extracted = new ExtractedPurchaseOrder(
                "12345", "ACME Corp", null, null, 500.0, null);
        when(llmExtractionService.extract(anyString())).thenReturn(extracted);

        when(poValidationService.validate(extracted)).thenReturn(
                new ValidationResult(DocumentStatus.COMPLETED, List.of(), List.of()));

        PurchaseOrder savedPo = new PurchaseOrder();
        savedPo.setId(5L);
        savedPo.setUser(testUser);
        savedPo.setDocument(savedDoc);
        when(purchaseOrderRepository.save(any(PurchaseOrder.class))).thenReturn(savedPo);

        DocumentResponse response = documentService.upload(file, 1L);

        assertThat(response).isNotNull();
        assertThat(response.fileName()).isEqualTo("order.docx");
        verify(documentRepository, atLeastOnce()).save(any(Document.class));
    }

    @Test
    void upload_docxByExtension_accepted() throws Exception {
        byte[] docxBytes = buildDocxBytes("PO Number: 99\nVendor: Widgets Inc\nTotal: 1200.00");

        // Content type is generic; extension is .docx
        MockMultipartFile file = new MockMultipartFile(
                "file", "purchase_order.docx",
                "application/octet-stream",
                docxBytes);

        when(documentRepository.findByUserIdAndFileHash(anyLong(), anyString()))
                .thenReturn(Optional.empty());
        when(userRepository.findById(1L)).thenReturn(Optional.of(testUser));

        Document savedDoc = new Document();
        savedDoc.setId(11L);
        savedDoc.setUser(testUser);
        savedDoc.setFileName("purchase_order.docx");
        savedDoc.setFileType("application/vnd.openxmlformats-officedocument.wordprocessingml.document");
        savedDoc.setStatus(DocumentStatus.PROCESSING);
        savedDoc.setUploadedAt(LocalDateTime.now());
        when(documentRepository.save(any(Document.class))).thenReturn(savedDoc);

        ExtractedPurchaseOrder extracted = new ExtractedPurchaseOrder(
                "99", "Widgets Inc", null, null, 1200.0, null);
        when(llmExtractionService.extract(anyString())).thenReturn(extracted);

        when(poValidationService.validate(extracted)).thenReturn(
                new ValidationResult(DocumentStatus.COMPLETED, List.of(), List.of()));

        PurchaseOrder savedPo = new PurchaseOrder();
        savedPo.setId(6L);
        savedPo.setUser(testUser);
        savedPo.setDocument(savedDoc);
        when(purchaseOrderRepository.save(any(PurchaseOrder.class))).thenReturn(savedPo);

        DocumentResponse response = documentService.upload(file, 1L);

        assertThat(response).isNotNull();
    }

    // -----------------------------------------------------------------------
    // DOCX validation — rejection cases
    // -----------------------------------------------------------------------

    @Test
    void upload_docFile_rejected() {
        // .doc (legacy Word) should be rejected
        MockMultipartFile file = new MockMultipartFile(
                "file", "order.doc",
                "application/msword",
                new byte[]{0x4D, 0x5A, 0x00, 0x00}); // random non-PDF bytes

        assertThatThrownBy(() -> documentService.upload(file, 1L))
                .isInstanceOf(ResponseStatusException.class)
                .satisfies(ex -> {
                    ResponseStatusException rse = (ResponseStatusException) ex;
                    assertThat(rse.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
                    assertThat(rse.getReason()).containsIgnoringCase("PDF and DOCX");
                });
    }

    @Test
    void upload_txtFile_rejected() {
        MockMultipartFile file = new MockMultipartFile(
                "file", "order.txt",
                "text/plain",
                "some purchase order text".getBytes());

        assertThatThrownBy(() -> documentService.upload(file, 1L))
                .isInstanceOf(ResponseStatusException.class)
                .satisfies(ex -> assertThat(((ResponseStatusException) ex).getStatusCode())
                        .isEqualTo(HttpStatus.BAD_REQUEST));
    }

    @Test
    void upload_corruptDocx_rejected() {
        // Bytes that look like DOCX name but contain garbage
        MockMultipartFile file = new MockMultipartFile(
                "file", "corrupt.docx",
                "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                new byte[]{0x00, 0x01, 0x02, 0x03, 0x04});

        assertThatThrownBy(() -> documentService.upload(file, 1L))
                .isInstanceOf(ResponseStatusException.class)
                .satisfies(ex -> {
                    ResponseStatusException rse = (ResponseStatusException) ex;
                    assertThat(rse.getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);
                });
    }

    @Test
    void upload_emptyDocx_textExtractionFails() throws Exception {
        byte[] docxBytes = buildEmptyDocxBytes();

        MockMultipartFile file = new MockMultipartFile(
                "file", "empty.docx",
                "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                docxBytes);

        when(documentRepository.findByUserIdAndFileHash(anyLong(), anyString()))
                .thenReturn(Optional.empty());

        assertThatThrownBy(() -> documentService.upload(file, 1L))
                .isInstanceOf(ResponseStatusException.class)
                .satisfies(ex -> {
                    ResponseStatusException rse = (ResponseStatusException) ex;
                    assertThat(rse.getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);
                    assertThat(rse.getReason()).containsIgnoringCase("No text");
                });
    }

    @Test
    void upload_docxOversized_rejected() {
        byte[] oversized = new byte[11 * 1024 * 1024]; // 11 MB

        MockMultipartFile file = new MockMultipartFile(
                "file", "big.docx",
                "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                oversized);

        assertThatThrownBy(() -> documentService.upload(file, 1L))
                .isInstanceOf(ResponseStatusException.class)
                .satisfies(ex -> {
                    ResponseStatusException rse = (ResponseStatusException) ex;
                    assertThat(rse.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
                    assertThat(rse.getReason()).containsIgnoringCase("10 MB");
                });
    }

    // -----------------------------------------------------------------------
    // Duplicate detection — DOCX hash
    // -----------------------------------------------------------------------

    @Test
    void upload_docxDuplicate_returnsDuplicateResponse() throws Exception {
        byte[] docxBytes = buildDocxBytes("Duplicate purchase order content");

        MockMultipartFile file = new MockMultipartFile(
                "file", "dup.docx",
                "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                docxBytes);

        Document existingDoc = new Document();
        existingDoc.setId(20L);
        existingDoc.setUser(testUser);
        existingDoc.setFileName("dup.docx");
        existingDoc.setFileType("application/vnd.openxmlformats-officedocument.wordprocessingml.document");
        existingDoc.setStatus(DocumentStatus.COMPLETED);
        existingDoc.setUploadedAt(LocalDateTime.now());

        PurchaseOrder existingPo = new PurchaseOrder();
        existingPo.setId(30L);
        existingPo.setUser(testUser);
        existingPo.setDocument(existingDoc);
        existingDoc.setPurchaseOrder(existingPo);

        when(documentRepository.findByUserIdAndFileHash(anyLong(), anyString()))
                .thenReturn(Optional.of(existingDoc));

        DocumentResponse response = documentService.upload(file, 1L);

        assertThat(response.duplicate()).isTrue();
        assertThat(response.purchaseOrderId()).isEqualTo(30L);
    }

    // -----------------------------------------------------------------------
    // Retry — hash must match original
    // -----------------------------------------------------------------------

    @Test
    void retry_docxHashMismatch_rejected() throws Exception {
        byte[] originalBytes = buildDocxBytes("Original content");
        byte[] differentBytes = buildDocxBytes("Different content");

        // Compute hash of original
        java.security.MessageDigest digest = java.security.MessageDigest.getInstance("SHA-256");
        String originalHash = java.util.HexFormat.of().formatHex(digest.digest(originalBytes));

        Document failedDoc = new Document();
        failedDoc.setId(40L);
        failedDoc.setUser(testUser);
        failedDoc.setFileName("order.docx");
        failedDoc.setFileType("application/vnd.openxmlformats-officedocument.wordprocessingml.document");
        failedDoc.setStatus(DocumentStatus.FAILED);
        failedDoc.setRetryable(true);
        failedDoc.setFileHash(originalHash);
        failedDoc.setUploadedAt(LocalDateTime.now());

        when(documentRepository.findById(40L)).thenReturn(Optional.of(failedDoc));

        MockMultipartFile differentFile = new MockMultipartFile(
                "file", "order.docx",
                "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                differentBytes);

        assertThatThrownBy(() -> documentService.retry(40L, 1L, differentFile))
                .isInstanceOf(ResponseStatusException.class)
                .satisfies(ex -> {
                    ResponseStatusException rse = (ResponseStatusException) ex;
                    assertThat(rse.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
                    assertThat(rse.getReason()).containsIgnoringCase("does not match");
                });
    }
}

package org.example.document;

import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.example.auth.UserRepository;
import org.example.entity.Document;
import org.example.entity.DocumentStatus;
import org.example.entity.PurchaseOrder;
import org.example.entity.User;
import org.example.purchaseorder.PurchaseOrderRepository;
import org.example.validation.PoValidationService;
import org.example.validation.ValidationResult;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.http.HttpStatus;
import org.springframework.mock.web.MockMultipartFile;
import org.springframework.web.server.ResponseStatusException;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

import static org.assertj.core.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for DocumentService — DOCX validation and text extraction.
 */
@ExtendWith(MockitoExtension.class)
class DocxDocumentServiceTest {

    @Mock DocumentRepository documentRepository;
    @Mock UserRepository userRepository;
    @Mock LlmExtractionService llmExtractionService;
    @Mock PurchaseOrderRepository purchaseOrderRepository;
    @Mock PoValidationService poValidationService;
    @Mock ObjectMapper objectMapper;

    @InjectMocks DocumentService documentService;

    private User testUser;

    @BeforeEach
    void setUp() {
        testUser = new User();
        testUser.setId(1L);
        testUser.setEmail("test@example.com");
    }

    // -----------------------------------------------------------------------
    // Helper: create a real DOCX byte array with given text content
    // -----------------------------------------------------------------------
    private byte[] buildDocxBytes(String paragraphText) throws IOException {
        try (XWPFDocument doc = new XWPFDocument()) {
            if (paragraphText != null && !paragraphText.isBlank()) {
                doc.createParagraph().createRun().setText(paragraphText);
            }
            ByteArrayOutputStream out = new ByteArrayOutputStream();
            doc.write(out);
            return out.toByteArray();
        }
    }

    private byte[] buildEmptyDocxBytes() throws IOException {
        return buildDocxBytes(null);
    }

    // -----------------------------------------------------------------------
    // DOCX validation — accepted content type
    // -----------------------------------------------------------------------

    @Test
    void upload_docxContentType_acceptedAndPersisted() throws Exception {
        byte[] docxBytes = buildDocxBytes("PO Number: 12345\nVendor: ACME Corp\nTotal: 500.00");

        MockMultipartFile file = new MockMultipartFile(
                "file", "order.docx",
                "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                docxBytes);

        when(documentRepository.findByUserIdAndFileHash(anyLong(), anyString()))
                .thenReturn(Optional.empty());
        when(userRepository.findById(1L)).thenReturn(Optional.of(testUser));

        Document savedDoc = new Document();
        savedDoc.setId(10L);
        savedDoc.setUser(testUser);
        savedDoc.setFileName("order.docx");
        savedDoc.setFileType("application/vnd.openxmlformats-officedocument.wordprocessingml.document");
        savedDoc.setStatus(DocumentStatus.PROCESSING);
        savedDoc.setUploadedAt(LocalDateTime.now());
        when(documentRepository.save(any(Document.class))).thenReturn(savedDoc);

        ExtractedPurchaseOrder extracted = new ExtractedPurchaseOrder(
                "12345", "ACME Corp", null, null, null, null, 500.0, null, null, List.of());
        when(llmExtractionService.extract(anyString())).thenReturn(extracted);

        when(poValidationService.validate(extracted)).thenReturn(
                new ValidationResult(DocumentStatus.COMPLETED, List.of(), List.of()));

        PurchaseOrder savedPo = new PurchaseOrder();
        savedPo.setId(5L);
        savedPo.setUser(testUser);
        savedPo.setDocument(savedDoc);
        when(purchaseOrderRepository.save(any(PurchaseOrder.class))).thenReturn(savedPo);

        DocumentResponse response = documentService.upload(file, 1L);

        assertThat(response).isNotNull();
        assertThat(response.fileName()).isEqualTo("order.docx");
        verify(documentRepository, atLeastOnce()).save(any(Document.class));
    }

    @Test
    void upload_docxByExtension_accepted() throws Exception {
        byte[] docxBytes = buildDocxBytes("PO Number: 99\nVendor: Widgets Inc\nTotal: 1200.00");

        // Content type is generic; extension is .docx
        MockMultipartFile file = new MockMultipartFile(
                "file", "purchase_order.docx",
                "application/octet-stream",
                docxBytes);

        when(documentRepository.findByUserIdAndFileHash(anyLong(), anyString()))
                .thenReturn(Optional.empty());
        when(userRepository.findById(1L)).thenReturn(Optional.of(testUser));

        Document savedDoc = new Document();
        savedDoc.setId(11L);
        savedDoc.setUser(testUser);
        savedDoc.setFileName("purchase_order.docx");
        savedDoc.setFileType("application/vnd.openxmlformats-officedocument.wordprocessingml.document");
        savedDoc.setStatus(DocumentStatus.PROCESSING);
        savedDoc.setUploadedAt(LocalDateTime.now());
        when(documentRepository.save(any(Document.class))).thenReturn(savedDoc);

        ExtractedPurchaseOrder extracted = new ExtractedPurchaseOrder(
                "99", "Widgets Inc", null, null, null, null, 1200.0, null, null, List.of());
        when(llmExtractionService.extract(anyString())).thenReturn(extracted);

        when(poValidationService.validate(extracted)).thenReturn(
                new ValidationResult(DocumentStatus.COMPLETED, List.of(), List.of()));

        PurchaseOrder savedPo = new PurchaseOrder();
        savedPo.setId(6L);
        savedPo.setUser(testUser);
        savedPo.setDocument(savedDoc);
        when(purchaseOrderRepository.save(any(PurchaseOrder.class))).thenReturn(savedPo);

        DocumentResponse response = documentService.upload(file, 1L);

        assertThat(response).isNotNull();
    }

    // -----------------------------------------------------------------------
    // DOCX validation — rejection cases
    // -----------------------------------------------------------------------

    @Test
    void upload_docFile_rejected() {
        // .doc (legacy Word) should be rejected
        MockMultipartFile file = new MockMultipartFile(
                "file", "order.doc",
                "application/msword",
                new byte[]{0x4D, 0x5A, 0x00, 0x00}); // random non-PDF bytes

        assertThatThrownBy(() -> documentService.upload(file, 1L))
                .isInstanceOf(ResponseStatusException.class)
                .satisfies(ex -> {
                    ResponseStatusException rse = (ResponseStatusException) ex;
                    assertThat(rse.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
                    assertThat(rse.getReason()).containsIgnoringCase("PDF and DOCX");
                });
    }

    @Test
    void upload_txtFile_rejected() {
        MockMultipartFile file = new MockMultipartFile(
                "file", "order.txt",
                "text/plain",
                "some purchase order text".getBytes());

        assertThatThrownBy(() -> documentService.upload(file, 1L))
                .isInstanceOf(ResponseStatusException.class)
                .satisfies(ex -> assertThat(((ResponseStatusException) ex).getStatusCode())
                        .isEqualTo(HttpStatus.BAD_REQUEST));
    }

    @Test
    void upload_corruptDocx_rejected() {
        // Bytes that look like DOCX name but contain garbage
        MockMultipartFile file = new MockMultipartFile(
                "file", "corrupt.docx",
                "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                new byte[]{0x00, 0x01, 0x02, 0x03, 0x04});

        assertThatThrownBy(() -> documentService.upload(file, 1L))
                .isInstanceOf(ResponseStatusException.class)
                .satisfies(ex -> {
                    ResponseStatusException rse = (ResponseStatusException) ex;
                    assertThat(rse.getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);
                });
    }

    @Test
    void upload_emptyDocx_textExtractionFails() throws Exception {
        byte[] docxBytes = buildEmptyDocxBytes();

        MockMultipartFile file = new MockMultipartFile(
                "file", "empty.docx",
                "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                docxBytes);

        when(documentRepository.findByUserIdAndFileHash(anyLong(), anyString()))
                .thenReturn(Optional.empty());

        assertThatThrownBy(() -> documentService.upload(file, 1L))
                .isInstanceOf(ResponseStatusException.class)
                .satisfies(ex -> {
                    ResponseStatusException rse = (ResponseStatusException) ex;
                    assertThat(rse.getStatusCode()).isEqualTo(HttpStatus.UNPROCESSABLE_ENTITY);
                    assertThat(rse.getReason()).containsIgnoringCase("No text");
                });
    }

    @Test
    void upload_docxOversized_rejected() {
        byte[] oversized = new byte[11 * 1024 * 1024]; // 11 MB

        MockMultipartFile file = new MockMultipartFile(
                "file", "big.docx",
                "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                oversized);

        assertThatThrownBy(() -> documentService.upload(file, 1L))
                .isInstanceOf(ResponseStatusException.class)
                .satisfies(ex -> {
                    ResponseStatusException rse = (ResponseStatusException) ex;
                    assertThat(rse.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
                    assertThat(rse.getReason()).containsIgnoringCase("10 MB");
                });
    }

    // -----------------------------------------------------------------------
    // Duplicate detection — DOCX hash
    // -----------------------------------------------------------------------

    @Test
    void upload_docxDuplicate_returnsDuplicateResponse() throws Exception {
        byte[] docxBytes = buildDocxBytes("Duplicate purchase order content");

        MockMultipartFile file = new MockMultipartFile(
                "file", "dup.docx",
                "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                docxBytes);

        Document existingDoc = new Document();
        existingDoc.setId(20L);
        existingDoc.setUser(testUser);
        existingDoc.setFileName("dup.docx");
        existingDoc.setFileType("application/vnd.openxmlformats-officedocument.wordprocessingml.document");
        existingDoc.setStatus(DocumentStatus.COMPLETED);
        existingDoc.setUploadedAt(LocalDateTime.now());

        PurchaseOrder existingPo = new PurchaseOrder();
        existingPo.setId(30L);
        existingPo.setUser(testUser);
        existingPo.setDocument(existingDoc);
        existingDoc.setPurchaseOrder(existingPo);

        when(documentRepository.findByUserIdAndFileHash(anyLong(), anyString()))
                .thenReturn(Optional.of(existingDoc));

        DocumentResponse response = documentService.upload(file, 1L);

        assertThat(response.duplicate()).isTrue();
        assertThat(response.purchaseOrderId()).isEqualTo(30L);
    }

    // -----------------------------------------------------------------------
    // Retry — hash must match original
    // -----------------------------------------------------------------------

    @Test
    void retry_docxHashMismatch_rejected() throws Exception {
        byte[] originalBytes = buildDocxBytes("Original content");
        byte[] differentBytes = buildDocxBytes("Different content");

        // Compute hash of original
        java.security.MessageDigest digest = java.security.MessageDigest.getInstance("SHA-256");
        String originalHash = java.util.HexFormat.of().formatHex(digest.digest(originalBytes));

        Document failedDoc = new Document();
        failedDoc.setId(40L);
        failedDoc.setUser(testUser);
        failedDoc.setFileName("order.docx");
        failedDoc.setFileType("application/vnd.openxmlformats-officedocument.wordprocessingml.document");
        failedDoc.setStatus(DocumentStatus.FAILED);
        failedDoc.setRetryable(true);
        failedDoc.setFileHash(originalHash);
        failedDoc.setUploadedAt(LocalDateTime.now());

        when(documentRepository.findById(40L)).thenReturn(Optional.of(failedDoc));

        MockMultipartFile differentFile = new MockMultipartFile(
                "file", "order.docx",
                "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                differentBytes);

        assertThatThrownBy(() -> documentService.retry(40L, 1L, differentFile))
                .isInstanceOf(ResponseStatusException.class)
                .satisfies(ex -> {
                    ResponseStatusException rse = (ResponseStatusException) ex;
                    assertThat(rse.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);
                    assertThat(rse.getReason()).containsIgnoringCase("does not match");
                });
    }
}

package org.example.user;

import org.example.auth.AuthService;
import org.example.auth.JwtService;
import org.example.auth.LoginRequest;
import org.example.auth.LoginResponse;
import org.example.auth.UserRepository;
import org.example.entity.User;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.http.HttpStatus;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.web.server.ResponseStatusException;

import java.util.Optional;

import static org.assertj.core.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for the name-update flow:
 *   updateProfile → persisted in DB → login returns the updated name.
 *
 * Covers the bug where login reused stale cached names instead of the
 * authoritative value from the database.
 */
@ExtendWith(MockitoExtension.class)
class UserServiceTest {

    @Mock UserRepository userRepository;
    @Mock PasswordEncoder passwordEncoder;
    @Mock JwtService jwtService;

    @InjectMocks UserService userService;
    @InjectMocks AuthService authService;

    private User user;

    @BeforeEach
    void setUp() {
        user = new User();
        user.setId(1L);
        user.setName("Original Name");
        user.setEmail("user@example.com");
        user.setPasswordHash("$2a$10$hashedpassword");
    }

    // ── updateProfile ─────────────────────────────────────────────────────────

    @Test
    void updateProfile_persistsNewNameInDatabase() {
        when(userRepository.findById(1L)).thenReturn(Optional.of(user));
        when(userRepository.save(any(User.class))).thenAnswer(inv -> inv.getArgument(0));

        UserProfileResponse response = userService.updateProfile(1L, new UpdateProfileRequest("New Name"));

        // Verify the entity was mutated and saved
        assertThat(user.getName()).isEqualTo("New Name");
        verify(userRepository).save(user);
        // Response immediately reflects the new name
        assertThat(response.name()).isEqualTo("New Name");
        assertThat(response.email()).isEqualTo("user@example.com");
    }

    @Test
    void updateProfile_stripsLeadingAndTrailingWhitespace() {
        when(userRepository.findById(1L)).thenReturn(Optional.of(user));
        when(userRepository.save(any(User.class))).thenAnswer(inv -> inv.getArgument(0));

        UserProfileResponse response = userService.updateProfile(1L, new UpdateProfileRequest("  Trimmed Name  "));

        assertThat(user.getName()).isEqualTo("Trimmed Name");
        assertThat(response.name()).isEqualTo("Trimmed Name");
    }

    @Test
    void updateProfile_updatesCorrectUser() {
        // Only the authenticated user's record should be updated
        when(userRepository.findById(1L)).thenReturn(Optional.of(user));
        when(userRepository.save(any(User.class))).thenAnswer(inv -> inv.getArgument(0));

        userService.updateProfile(1L, new UpdateProfileRequest("Updated"));

        verify(userRepository).findById(1L);
        verify(userRepository, never()).findById(argThat(id -> !id.equals(1L)));
    }

    // ── Validation ────────────────────────────────────────────────────────────

    @Test
    void updateProfile_emptyName_throwsBadRequest() {
        assertThatThrownBy(() -> userService.updateProfile(1L, new UpdateProfileRequest("")))
                .isInstanceOf(ResponseStatusException.class)
                .satisfies(ex -> assertThat(((ResponseStatusException) ex).getStatusCode())
                        .isEqualTo(HttpStatus.BAD_REQUEST));

        verify(userRepository, never()).save(any());
    }

    @Test
    void updateProfile_blankName_throwsBadRequest() {
        assertThatThrownBy(() -> userService.updateProfile(1L, new UpdateProfileRequest("   ")))
                .isInstanceOf(ResponseStatusException.class)
                .satisfies(ex -> assertThat(((ResponseStatusException) ex).getStatusCode())
                        .isEqualTo(HttpStatus.BAD_REQUEST));
    }

    @Test
    void updateProfile_nullName_throwsBadRequest() {
        assertThatThrownBy(() -> userService.updateProfile(1L, new UpdateProfileRequest(null)))
                .isInstanceOf(ResponseStatusException.class)
                .satisfies(ex -> assertThat(((ResponseStatusException) ex).getStatusCode())
                        .isEqualTo(HttpStatus.BAD_REQUEST));
    }

    @Test
    void updateProfile_nameTooLong_throwsBadRequest() {
        String tooLong = "A".repeat(101);
        assertThatThrownBy(() -> userService.updateProfile(1L, new UpdateProfileRequest(tooLong)))
                .isInstanceOf(ResponseStatusException.class)
                .satisfies(ex -> assertThat(((ResponseStatusException) ex).getStatusCode())
                        .isEqualTo(HttpStatus.BAD_REQUEST));
    }

    @Test
    void updateProfile_exactly100Chars_succeeds() {
        String exactly100 = "A".repeat(100);
        when(userRepository.findById(1L)).thenReturn(Optional.of(user));
        when(userRepository.save(any(User.class))).thenAnswer(inv -> inv.getArgument(0));

        assertThatCode(() -> userService.updateProfile(1L, new UpdateProfileRequest(exactly100)))
                .doesNotThrowAnyException();
    }

    // ── Login returns updated name (the bug fix) ──────────────────────────────

    @Test
    void login_afterNameUpdate_returnsUpdatedNameFromDatabase() {
        // Simulate: user updates their name in the DB
        user.setName("Updated Name");

        // Login reads from DB — must return the updated name, not any cached value
        when(userRepository.findByEmail("user@example.com")).thenReturn(Optional.of(user));
        when(passwordEncoder.matches("correctpass", user.getPasswordHash())).thenReturn(true);
        when(jwtService.generateToken(1L)).thenReturn("jwt-token");

        LoginResponse response = authService.login(new LoginRequest("user@example.com", "correctpass"));

        assertThat(response.token()).isEqualTo("jwt-token");
        assertThat(response.name()).isEqualTo("Updated Name"); // authoritative from DB
        assertThat(response.email()).isEqualTo("user@example.com");
    }

    @Test
    void login_returnsNameAndEmailFromDatabase_notCachedValues() {
        // This test documents the contract: login response ALWAYS contains DB values.
        // Previously the frontend used stale localStorage; now it uses the response.
        when(userRepository.findByEmail("user@example.com")).thenReturn(Optional.of(user));
        when(passwordEncoder.matches("pass", user.getPasswordHash())).thenReturn(true);
        when(jwtService.generateToken(1L)).thenReturn("token");

        LoginResponse response = authService.login(new LoginRequest("user@example.com", "pass"));

        assertThat(response.name()).isNotNull().isNotBlank();
        assertThat(response.email()).isEqualTo("user@example.com");
    }

    // ── getProfile ────────────────────────────────────────────────────────────

    @Test
    void getProfile_returnsCurrentNameFromDatabase() {
        when(userRepository.findById(1L)).thenReturn(Optional.of(user));

        UserProfileResponse profile = userService.getProfile(1L);

        assertThat(profile.name()).isEqualTo("Original Name");
        assertThat(profile.email()).isEqualTo("user@example.com");
        assertThat(profile.id()).isEqualTo(1L);
    }
}

package org.example.validation;

import org.example.document.ExtractedPurchaseOrder;
import org.example.entity.DocumentStatus;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * Unit tests for PoValidationService — deterministic validation layer.
 */
class PoValidationServiceTest {

    private final PoValidationService svc = new PoValidationService();

    // ── Helper builders ───────────────────────────────────────────────────────

    private static ExtractedPurchaseOrder.ExtractedLineItem item(
            String desc, Double qty, Double unitPrice, Double totalPrice) {
        return new ExtractedPurchaseOrder.ExtractedLineItem(desc, qty, unitPrice, totalPrice);
    }

    private static ExtractedPurchaseOrder po(String poNum, String vendor, String date,
                                              Double total,
                                              List<ExtractedPurchaseOrder.ExtractedLineItem> items) {
        return new ExtractedPurchaseOrder(poNum, vendor, date, "Net 30", total, items);
    }

    // ── COMPLETED ─────────────────────────────────────────────────────────────

    @Test
    void completed_whenAllFieldsValid() {
        var result = svc.validate(po("PO-001", "ACME Corp", "2024-01-15", 250000.00,
                List.of(item("Widget", 5.0, 50000.0, 250000.0))));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.COMPLETED);
        assertThat(result.corrections()).isEmpty();
        assertThat(result.reviewReasons()).isEmpty();
    }

    @Test
    void completed_missingOptionalFieldsDoNotFail() {
        // deliveryDate, currency, subtotal, tax are optional — should not cause NEEDS_REVIEW
        var result = svc.validate(po("PO-001", "ACME Corp", null, null, List.of()));

        // Missing date is OK; missing total is OK
        assertThat(result.outcome()).isEqualTo(DocumentStatus.COMPLETED);
    }

    // ── Correct line totals ───────────────────────────────────────────────────

    @Test
    void completed_correctLineTotalNoCorrection() {
        // 5 × 50000 = 250000 — extracted value is correct
        var result = svc.validate(po("PO-001", "ACME", "2024-01-15", 250000.0,
                List.of(item("Item A", 5.0, 50000.0, 250000.0))));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.COMPLETED);
        assertThat(result.corrections()).isEmpty();
    }

    // ── Incorrect line totals → automatic correction ──────────────────────────

    @Test
    void correctedWithCorrections_whenLineTotalWrong_grandTotalMatchesCorrected() {
        // 5 × 50000 = 250000; extracted line total is wrong (200000) but grand total
        // matches the CORRECTED sum (250000) → safe to correct, no ambiguity.
        var result = svc.validate(po("PO-001", "ACME", "2024-01-15", 250000.0,
                List.of(item("Item A", 5.0, 50000.0, 200000.0))));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.COMPLETED_WITH_CORRECTIONS);
        assertThat(result.corrections()).hasSize(1);

        var correction = result.corrections().get(0);
        assertThat(correction.field()).isEqualTo("items[0].totalPrice");
        assertThat(correction.originalValue()).isEqualTo(200000.0);
        assertThat(correction.correctedValue()).isEqualTo(250000.0);
        assertThat(correction.reason()).contains("5.0 × 50000.0");
    }

    @Test
    void correctedWithCorrections_whenLineTotalCorrectedAndGrandTotalAlsoLow() {
        // 5 × 50000 = 250000; extracted line total wrong (200000) AND grand total = 200000.
        // After line correction, lineSum = 250000 > grandTotal = 200000.
        // lineSum > grandTotal → auto-correct grandTotal to 250000 as well.
        var result = svc.validate(po("PO-001", "ACME", "2024-01-15", 200000.0,
                List.of(item("Item A", 5.0, 50000.0, 200000.0))));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.COMPLETED_WITH_CORRECTIONS);
        // Two corrections: line total and grand total
        assertThat(result.corrections()).hasSize(2);
        assertThat(result.corrections()).anyMatch(c -> c.field().equals("items[0].totalPrice"));
        assertThat(result.corrections()).anyMatch(c -> c.field().equals("grandTotal") && c.correctedValue() == 250000.0);
        assertThat(result.reviewReasons()).isEmpty();
    }

    @Test
    void correctedWithCorrections_multipleLineTotals() {
        // Line 0 correct, Line 1 wrong
        var result = svc.validate(po("PO-002", "Vendor", "2024-02-01", null, List.of(
                item("A", 2.0, 100.0, 200.0),   // correct
                item("B", 3.0, 100.0, 200.0)    // wrong: should be 300
        )));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.COMPLETED_WITH_CORRECTIONS);
        assertThat(result.corrections()).hasSize(1);
        assertThat(result.corrections().get(0).field()).isEqualTo("items[1].totalPrice");
        assertThat(result.corrections().get(0).correctedValue()).isEqualTo(300.0);
    }

    // ── Missing line total → filled in ───────────────────────────────────────

    @Test
    void correctedWithCorrections_missingLineTotalFilledIn() {
        var result = svc.validate(po("PO-003", "Vendor", "2024-01-01", null,
                List.of(item("Widget", 10.0, 25.0, null))));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.COMPLETED_WITH_CORRECTIONS);
        assertThat(result.corrections()).hasSize(1);
        assertThat(result.corrections().get(0).correctedValue()).isEqualTo(250.0);
        assertThat(result.corrections().get(0).originalValue()).isNull();
    }

    // ── Subtotal correction ───────────────────────────────────────────────────

    // The current schema doesn't have a separate subtotal field in ExtractedPurchaseOrder;
    // grand-total correction is handled in the next test.

    // ── Grand total correction when deterministically calculable ──────────────

    @Test
    void needsReview_whenGrandTotalHigherThanLineSum_taxPossible() {
        // Lines sum to 250000 but grand total is 290000 — could be tax.
        // We flag NEEDS_REVIEW so a human can confirm whether it's tax or an error.
        var result = svc.validate(po("PO-001", "ACME", "2024-01-15", 290000.0,
                List.of(item("Item A", 5.0, 50000.0, 250000.0))));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.NEEDS_REVIEW);
        assertThat(result.corrections()).isEmpty(); // no auto-correction
        assertThat(result.reviewReasons()).anyMatch(r -> r.contains("higher than"));
    }

    @Test
    void corrected_whenGrandTotalLowerThanLineSum() {
        // Lines sum to 250000 but grand total is 200000 → definitively wrong → auto-correct
        var result = svc.validate(po("PO-001", "ACME", "2024-01-15", 200000.0,
                List.of(item("Item A", 5.0, 50000.0, 250000.0))));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.COMPLETED_WITH_CORRECTIONS);
        assertThat(result.corrections()).anyMatch(c ->
                c.field().equals("grandTotal") && c.correctedValue() == 250000.0);
    }

    // ── Rounding tolerance ────────────────────────────────────────────────────

    @Test
    void completed_withinRoundingTolerance() {
        // 3 × 33.33 = 99.99 but extracted says 100.00 (within 0.02 tolerance)
        var result = svc.validate(po("PO-001", "ACME", "2024-01-15", null,
                List.of(item("Service", 3.0, 33.33, 100.00))));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.COMPLETED);
        assertThat(result.corrections()).isEmpty();
    }

    @Test
    void corrected_outsideRoundingTolerance() {
        // 3 × 33.33 = 99.99, but extracted says 98.00 (outside 0.02 tolerance)
        var result = svc.validate(po("PO-001", "ACME", "2024-01-15", null,
                List.of(item("Service", 3.0, 33.33, 98.00))));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.COMPLETED_WITH_CORRECTIONS);
        assertThat(result.corrections()).hasSize(1);
    }

    // ── Original extracted value and correction reason are preserved ──────────

    @Test
    void correctionPreservesOriginalValueAndReason() {
        // Grand total matches the corrected line sum — safe correction, no ambiguity.
        var result = svc.validate(po("PO-001", "ACME", "2024-01-15", 250000.0,
                List.of(item("Item A", 5.0, 50000.0, 200000.0))));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.COMPLETED_WITH_CORRECTIONS);
        var c = result.corrections().get(0);
        assertThat(c.originalValue()).isEqualTo(200000.0);
        assertThat(c.correctedValue()).isEqualTo(250000.0);
        assertThat(c.reason()).isNotBlank();
    }

    // ── Grand-total mismatch ──────────────────────────────────────────────────

    @Test
    void correctedWithCorrections_grandTotalLowerThanLineSum_autoCorrects() {
        // Line sum = 400000, grand total = 200000 → lineSum > grandTotal → auto-correct
        var result = svc.validate(po("PO-001", "ACME", "2024-01-15", 200000.0,
                List.of(
                        item("Item A", 5.0, 50000.0, 250000.0),
                        item("Item B", 10.0, 15000.0, 150000.0)
                )));
        assertThat(result.outcome()).isEqualTo(DocumentStatus.COMPLETED_WITH_CORRECTIONS);
        assertThat(result.corrections()).anyMatch(c ->
                c.field().equals("grandTotal") && c.correctedValue() == 400000.0);
        assertThat(result.reviewReasons()).isEmpty();
    }

    @Test
    void needsReview_grandTotalHigherThanLineSum_flaggedForReview() {
        // Line sum = 400000, grand total = 800000 → grandTotal > lineSum → NEEDS_REVIEW
        // (could be tax, could be error — human should decide)
        var result = svc.validate(po("PO-001", "ACME", "2024-01-15", 800000.0,
                List.of(
                        item("Item A", 5.0, 50000.0, 250000.0),
                        item("Item B", 10.0, 15000.0, 150000.0)
                )));
        assertThat(result.outcome()).isEqualTo(DocumentStatus.NEEDS_REVIEW);
        assertThat(result.reviewReasons()).anyMatch(r -> r.contains("higher than"));
    }

    // ── NEEDS_REVIEW ─────────────────────────────────────────────────────────

    @Test
    void needsReview_missingPoNumber() {
        var result = svc.validate(po(null, "ACME", "2024-01-15", 1000.0, List.of()));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.NEEDS_REVIEW);
        assertThat(result.reviewReasons()).anyMatch(r -> r.contains("PO number"));
    }

    @Test
    void needsReview_blankPoNumber() {
        var result = svc.validate(po("   ", "ACME", "2024-01-15", 1000.0, List.of()));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.NEEDS_REVIEW);
    }

    @Test
    void needsReview_missingVendor() {
        var result = svc.validate(po("PO-001", null, "2024-01-15", 1000.0, List.of()));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.NEEDS_REVIEW);
        assertThat(result.reviewReasons()).anyMatch(r -> r.contains("Vendor"));
    }

    @Test
    void needsReview_invalidDate() {
        var result = svc.validate(po("PO-001", "ACME", "not-a-date", 1000.0, List.of()));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.NEEDS_REVIEW);
        assertThat(result.reviewReasons()).anyMatch(r -> r.contains("date"));
    }

    @Test
    void needsReview_negativeQuantity() {
        var result = svc.validate(po("PO-001", "ACME", "2024-01-15", null,
                List.of(item("Widget", -1.0, 100.0, -100.0))));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.NEEDS_REVIEW);
        assertThat(result.reviewReasons()).anyMatch(r -> r.contains("quantity"));
    }

    @Test
    void needsReview_zeroQuantity() {
        var result = svc.validate(po("PO-001", "ACME", "2024-01-15", null,
                List.of(item("Widget", 0.0, 100.0, 0.0))));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.NEEDS_REVIEW);
        assertThat(result.reviewReasons()).anyMatch(r -> r.contains("quantity"));
    }

    // ── Missing optional fields should NOT cause failure ─────────────────────

    @Test
    void completed_whenOptionalFieldsMissing() {
        // paymentTerms, currency, deliveryDate, subtotal, tax, totalAmount all null
        var extracted = new ExtractedPurchaseOrder("PO-001", "ACME", "2024-01-15",
                null, null, List.of());
        var result = svc.validate(extracted);

        assertThat(result.outcome()).isEqualTo(DocumentStatus.COMPLETED);
    }

    // ── Discounts/tax/shipping handling ──────────────────────────────────────

    @Test
    void needsReview_grandTotalHigherThanLineSum_possiblyTax() {
        // Items sum to 1000, grand total is 1180 (likely tax = 180).
        // We cannot tell if it's tax or an error → flag NEEDS_REVIEW so a human decides.
        var result = svc.validate(po("PO-100", "Supplier", "2024-03-01", 1180.0,
                List.of(
                        item("Product A", 10.0, 50.0, 500.0),
                        item("Product B", 10.0, 50.0, 500.0)
                )));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.NEEDS_REVIEW);
        assertThat(result.corrections()).isEmpty(); // no auto-correction for high total
        assertThat(result.reviewReasons()).anyMatch(r -> r.contains("higher than"));
    }

    @Test
    void completed_whenGrandTotalMatchesLineSum_exactlyNoTax() {
        // Items sum to 1000, grand total is exactly 1000 → COMPLETED
        var result = svc.validate(po("PO-100", "Supplier", "2024-03-01", 1000.0,
                List.of(
                        item("Product A", 10.0, 50.0, 500.0),
                        item("Product B", 10.0, 50.0, 500.0)
                )));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.COMPLETED);
        assertThat(result.corrections()).isEmpty();
    }

    // ── NEEDS_REVIEW does not turn to FAILED ────────────────────────────────

    @Test
    void needsReview_notFailed() {
        var result = svc.validate(po(null, null, "2024-01-15", 500.0, List.of()));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.NEEDS_REVIEW);
        assertThat(result.outcome()).isNotEqualTo(DocumentStatus.FAILED);
    }
}

package org.example.validation;

import org.example.document.ExtractedPurchaseOrder;
import org.example.entity.DocumentStatus;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * Unit tests for PoValidationService — deterministic validation layer.
 */
class PoValidationServiceTest {

    private final PoValidationService svc = new PoValidationService();

    // ── Helper builders ───────────────────────────────────────────────────────

    private static ExtractedPurchaseOrder.ExtractedLineItem item(
            String desc, Double qty, Double unitPrice, Double totalPrice) {
        return new ExtractedPurchaseOrder.ExtractedLineItem(desc, qty, unitPrice, totalPrice);
    }

    private static ExtractedPurchaseOrder po(String poNum, String vendor, String date,
                                              Double total,
                                              List<ExtractedPurchaseOrder.ExtractedLineItem> items) {
        return new ExtractedPurchaseOrder(poNum, vendor, date, null, "Net 30", null, null, null, total, items);
    }

    // ── COMPLETED ─────────────────────────────────────────────────────────────

    @Test
    void completed_whenAllFieldsValid() {
        var result = svc.validate(po("PO-001", "ACME Corp", "2024-01-15", 250000.00,
                List.of(item("Widget", 5.0, 50000.0, 250000.0))));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.COMPLETED);
        assertThat(result.corrections()).isEmpty();
        assertThat(result.reviewReasons()).isEmpty();
    }

    @Test
    void completed_missingOptionalFieldsDoNotFail() {
        // deliveryDate, currency, subtotal, tax are optional — should not cause NEEDS_REVIEW
        var result = svc.validate(po("PO-001", "ACME Corp", null, null, List.of()));

        // Missing date is OK; missing total is OK
        assertThat(result.outcome()).isEqualTo(DocumentStatus.COMPLETED);
    }

    // ── Correct line totals ───────────────────────────────────────────────────

    @Test
    void completed_correctLineTotalNoCorrection() {
        // 5 × 50000 = 250000 — extracted value is correct
        var result = svc.validate(po("PO-001", "ACME", "2024-01-15", 250000.0,
                List.of(item("Item A", 5.0, 50000.0, 250000.0))));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.COMPLETED);
        assertThat(result.corrections()).isEmpty();
    }

    // ── Incorrect line totals → automatic correction ──────────────────────────

    @Test
    void correctedWithCorrections_whenLineTotalWrong_grandTotalMatchesCorrected() {
        // 5 × 50000 = 250000; extracted line total is wrong (200000) but grand total
        // matches the CORRECTED sum (250000) → safe to correct, no ambiguity.
        var result = svc.validate(po("PO-001", "ACME", "2024-01-15", 250000.0,
                List.of(item("Item A", 5.0, 50000.0, 200000.0))));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.COMPLETED_WITH_CORRECTIONS);
        assertThat(result.corrections()).hasSize(1);

        var correction = result.corrections().get(0);
        assertThat(correction.field()).isEqualTo("items[0].totalPrice");
        assertThat(correction.originalValue()).isEqualTo(200000.0);
        assertThat(correction.correctedValue()).isEqualTo(250000.0);
        assertThat(correction.reason()).contains("5.0 × 50000.0");
    }

    @Test
    void correctedWithCorrections_whenLineTotalCorrectedAndGrandTotalAlsoLow() {
        // 5 × 50000 = 250000; extracted line total wrong (200000) AND grand total = 200000.
        // After line correction, lineSum = 250000 > grandTotal = 200000.
        // lineSum > grandTotal → auto-correct grandTotal to 250000 as well.
        var result = svc.validate(po("PO-001", "ACME", "2024-01-15", 200000.0,
                List.of(item("Item A", 5.0, 50000.0, 200000.0))));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.COMPLETED_WITH_CORRECTIONS);
        // Two corrections: line total and grand total
        assertThat(result.corrections()).hasSize(2);
        assertThat(result.corrections()).anyMatch(c -> c.field().equals("items[0].totalPrice"));
        assertThat(result.corrections()).anyMatch(c -> c.field().equals("grandTotal") && c.correctedValue() == 250000.0);
        assertThat(result.reviewReasons()).isEmpty();
    }

    @Test
    void correctedWithCorrections_multipleLineTotals() {
        // Line 0 correct, Line 1 wrong
        var result = svc.validate(po("PO-002", "Vendor", "2024-02-01", null, List.of(
                item("A", 2.0, 100.0, 200.0),   // correct
                item("B", 3.0, 100.0, 200.0)    // wrong: should be 300
        )));

        assertThat(result.outcome()).isEqualTo(DocumentStatus.COMPLETED_WITH_CORRECTIONS);
        assertThat(result.corrections()).hasSize(1);
        assertThat(result.corrections().get(0).field()).isEqualTo("items[1].totalPrice");
        assertThat(result.corrections().get(0).correctedValue()).isEqualTo(300.0);
    }

    // ── Missing line total → filled in ───────────────────────────────────────

    @Test
